contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // precondition required by C.transfer: _tos.length > 0
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        // call transfer and capture whether it reverts and its return value
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: for any valid inputs (non-empty _tos), transfer never reverts and returns true
        assert(!reverted && ret == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        // record contract balance before
        uint balBefore = address(c).balance;
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        uint balAfter = address(c).balance;
        // General rule: for any non-empty _tos, transfer does not revert, returns true, and does not change c's ether balance
        assert(!reverted && ret == true && balAfter == balBefore);
    }
    receive() external payable { }
}

